// SPDX-License-Identifier: AGPL-3.0-or-later
//
// Provider mapping engine for resource facts (ADR-0073): Cloudflare and Google.
//
// What is read is DATA: `mappings/<provider>.json` names, per resource type,
// the attribute paths to copy, the ids kept as join keys, the nested lists, and
// the relations. At load each mapping is validated against ITS OWN vendored
// projection of the provider's published schema (`spec/<provider>.schema.json`,
// generated by gen/facts-spec.mjs): an unknown or sensitive attribute,
// or a non-scalar read, stops the module from loading. Anything the mapping
// does not name is never read: not a Worker's source, a binding's value, a
// tunnel secret. `pickPublic` then drops any named attribute the document
// itself marks sensitive.
//
// Relations are exact value equality on mapped join attributes. A value that
// matches nothing resolves to null; nothing is guessed by name. A relation may
// list several target attributes to try, scope attributes that must agree, and
// a prefix to strip (see resolveScoped): all three are data, and none is
// specific to a provider. In a PLAN
// document only, a relation the values cannot resolve (the value is unknown
// until apply) may resolve through the configuration's references, and only
// when exactly one referenced address has the target type.

// The mappings and specs are imported, not read from disk next to this file,
// so that a bundler carries them: `cloister inspect` ships as one file
// (gen/bundle.mjs), and there is no directory beside it to read from.
import cloudflareMapping from "./mappings/cloudflare.json" with { type: "json" };
import googleMapping from "./mappings/google.json" with { type: "json" };
import kubernetesMapping from "./mappings/kubernetes.json" with { type: "json" };
import cloudflareSpec from "./spec/cloudflare.schema.json" with { type: "json" };
import googleSpec from "./spec/google.schema.json" with { type: "json" };
import kubernetesApiSpec from "./spec/kubernetes-api.schema.json" with { type: "json" };
import kubernetesObjectMeta from "./spec/kubernetes-object-meta.schema.json" with { type: "json" };
import knativeServingSpec from "./spec/knative-serving.schema.json" with { type: "json" };
import kubernetesSpec from "./spec/kubernetes.schema.json" with { type: "json" };

import { atRow, deepFreeze, entryOf, isMarkedSensitive, makeFact, pickPublic } from "./facts.mjs";
import { expandMapping, heldObject, objectKind, objectType } from "./mapping.mjs";
import { validateMapping } from "./validate.mjs";
import { SITES, configuredRows, expressionSources } from "./terraform.mjs";

/**
 * A mapping, with every `like` resolved (see mapping.mjs), and frozen all the
 * way down: it is validated once, at load, so nothing may change it after.
 */
const readMapping = (mapping) => deepFreeze(expandMapping(structuredClone(mapping)));
const readSpec = (spec) => deepFreeze(structuredClone(spec));

export const CLOUDFLARE_MAPPING = readMapping(cloudflareMapping);
export const CLOUDFLARE_SPEC = readSpec(cloudflareSpec);
validateMapping(CLOUDFLARE_MAPPING, CLOUDFLARE_SPEC);
export const GOOGLE_MAPPING = readMapping(googleMapping);
export const GOOGLE_SPEC = readSpec(googleSpec);
validateMapping(GOOGLE_MAPPING, GOOGLE_SPEC);
export const KUBERNETES_MAPPING = readMapping(kubernetesMapping);
export const KUBERNETES_SPEC = readSpec(kubernetesSpec);
// The objects a `kubernetes_manifest` holds are checked against the published
// schema of their API, which the provider leaves to the API server:
// Kubernetes' own for its kinds, and a custom resource's CRD for that kind.
export const KUBERNETES_API_SPEC = readSpec(kubernetesApiSpec);
export const KNATIVE_SERVING_SPEC = readSpec(knativeServingSpec);
export const KUBERNETES_OBJECT_SPECS = Object.freeze([KUBERNETES_API_SPEC, KNATIVE_SERVING_SPEC]);
// ObjectMeta as Kubernetes defines it, for a CRD a checkout supplies: a CRD
// does not describe its kinds' metadata (see object-spec.mjs).
export const KUBERNETES_OBJECT_META = readSpec(kubernetesObjectMeta);
validateMapping(KUBERNETES_MAPPING, KUBERNETES_SPEC, KUBERNETES_OBJECT_SPECS);

/**
 * The source each entry's facts carry: the provider of the mapping that holds
 * the entry. An entry a checkout supplies is held by the mapping whose
 * resource holds its objects, so its facts carry that provider too.
 */
const SOURCE_OF = new WeakMap();
const registerSources = (mapping) => {
  for (const entry of Object.values(mapping.types)) if (!SOURCE_OF.has(entry)) SOURCE_OF.set(entry, `terraform:${mapping.provider.split("/").pop()}`);
};

const WORKER_TYPE = "cloudflare_workers_script";
const BINDING_RELATIONS = CLOUDFLARE_MAPPING.bindingRelations;

/**
 * Own-property lookups only. A resource or binding type comes from the
 * document, and `toString` or `constructor` must not find Object.prototype.
 */
const own = (table, key) => (typeof key === "string" && Object.hasOwn(table, key) ? table[key] : undefined);
const relationsFor = (binding) => own(BINDING_RELATIONS, binding?.type) ?? [];
/**
 * The mappings one run reads with, validated before they are put here.
 * Cloister's own (SHIPPED) are the default. A checkout's entries make another
 * set, with them added (checkout.mjs). Each fact holds the entry that read it
 * (entryOf), so what follows from a fact never looks its type up again.
 */
export function makeRegistry(mappings) {
  const list = Object.freeze([...mappings]);
  for (const mapping of list) registerSources(mapping);
  const mappedType = (type) => {
    for (const mapping of list) {
      const entry = own(mapping.types, type);
      if (entry) return entry;
    }
    return undefined;
  };
  return Object.freeze({
    mappings: list,
    /** The mapping entry for a resource type, or undefined when no mapping has it. */
    mappedType,
    /** Every `[type, entry]` across all mappings, in declaration order. */
    mappedEntries: () => list.flatMap((mapping) => Object.entries(mapping.types)),
    /** True for a type that reads an object a resource holds whole (see mapping.mjs). */
    readsHeldObject: (type) => list.some((mapping) => objectKind(mapping, type)?.object !== undefined),
    entryFor: (resource) => entryIn(list, mappedType, resource),
  });
}

/** Cloister's own mappings, read when a checkout supplies none. */
export const SHIPPED = makeRegistry([CLOUDFLARE_MAPPING, GOOGLE_MAPPING, KUBERNETES_MAPPING]);
export const { mappedType, mappedEntries, readsHeldObject, entryFor } = SHIPPED;

/**
 * The entry that reads a resource, and the resource as that entry reads it.
 *
 * Most resources are read as they are. A resource that holds an object of
 * another API whole (a mapping's `objects`) is read as that object, by the
 * entry for its kind: the type becomes `<resource type> <values of by>`, and
 * the values and sensitivity markers become the object's. The address stays
 * the resource's, so the configuration's references still find it.
 *
 * Returns `{ skipped }`, the name to count as not read, when no entry reads
 * it: the resource type, or for a held object the type of its kind, so the
 * report names the kind it did not read. An object whose kind cannot be read
 * (absent, not text, or marked sensitive) is counted as the resource type
 * with "(kind not stated)".
 */
function entryIn(mappings, mappedTypeIn, resource) {
  for (const mapping of mappings) {
    const object = heldObject(mapping, resource.type);
    if (!object) continue;
    const value = own(resource.values, object.attr);
    // A resource marked whole (malformed markers are read as that) marks its object whole.
    const marker = resource.sensitive === true ? true : own(resource.sensitive ?? {}, object.attr);
    const unread = { skipped: `${resource.type} (kind not stated)` };
    if (!value || typeof value !== "object" || Array.isArray(value)) return unread;
    // The whole object marked sensitive, or a marker of any other shape: nothing in it is read.
    if (marker !== undefined && marker !== false && (marker === null || typeof marker !== "object" || Array.isArray(marker))) return unread;
    const values = [];
    for (const field of object.by) {
      const at = own(value, field);
      if (typeof at !== "string" || !/^\S+$/.test(at) || isMarkedSensitive(marker?.[field])) return unread;
      values.push(at);
    }
    const type = objectType(resource.type, values);
    const entry = own(mapping.types, type);
    if (!entry) return { skipped: type };
    return {
      entry,
      resource: { ...resource, type, values: value, sensitive: marker && typeof marker === "object" ? marker : {}, heldIn: object.attr },
    };
  }
  // A document's type is a Terraform identifier. One with a space would be
  // read as a kind of held object without the object saying what it is.
  if (/\s/.test(resource.type)) return { skipped: resource.type };
  const entry = mappedTypeIn(resource.type);
  return entry ? { entry, resource } : { skipped: resource.type };
}
/** Fact types that count as a Worker when a relation targets a Worker script. */
const WORKER_FACT_TYPES = new Set([WORKER_TYPE, "wrangler_worker", "cloudflare_worker"]);
/** Fact types whose NAME is the Worker's script name. */
const NAME_IS_SCRIPT_NAME = new Set(["wrangler_worker", "cloudflare_worker"]);

/**
 * A single nested block is rendered as a list of one (`metadata: [{ name }]`).
 * A scalar path reads through it. A list of none, or of several, has no one
 * value for a scalar path, so it reads as absent.
 */
const single = (o) => (Array.isArray(o) ? (o.length === 1 ? o[0] : undefined) : o);
const getPath = (obj, path) => path.split(".").reduce((o, k) => {
  const at = single(o);
  return at && typeof at === "object" ? at[k] : undefined;
}, obj);

/**
 * The sensitivity marker for the value at `path`, walked beside the value.
 *
 * A container the document marks whole (`true`) marks everything under it,
 * so the walk stops there and returns `true`. Walking on, as `getPath` does
 * for a value, would find no marker under a `true` and read the value as
 * public. A single nested block's marker is a list of one, like its value; a
 * marker list of any other length, or a marker of any other shape, is
 * malformed and also returns `true`: fail closed.
 */
function markerAt(sensitive, path) {
  let marker = sensitive;
  for (const segment of path.split(".")) {
    marker = unwrapMarker(marker);
    if (marker === undefined) return undefined;
    if (marker === true) return true;
    marker = marker[segment];
  }
  return marker;
}

/** A marker with a list of one unwrapped: an object, `undefined` (nothing marked), or `true`. */
function unwrapMarker(marker) {
  if (marker === undefined || marker === false) return undefined;
  if (Array.isArray(marker)) {
    if (marker.length !== 1) return true;
    return unwrapMarker(marker[0]);
  }
  return marker !== null && typeof marker === "object" ? marker : true;
}

function pickPath(values, sensitive, path) {
  const parts = path.split(".");
  const key = parts.pop();
  const v = parts.length ? single(getPath(values, parts.join("."))) : values;
  const s = parts.length ? unwrapMarker(markerAt(sensitive, parts.join("."))) : sensitive;
  return pickPublic(v, s, [key])[key];
}

/**
 * The rows of a list at `segments`, each with its own sensitivity marker.
 *
 * A path may pass THROUGH lists on the way: a Cloud Run service's
 * `template.containers.env` is a list (`template`) of lists (`containers`) of
 * rows (`env`), and every container's rows are wanted. The values and the
 * document's `sensitive_values` are walked side by side, because a marker
 * means something only at the same position as its value.
 *
 * A well-formed document gives a list either no marker, or an array with one
 * marker per element. `true` means the whole list is sensitive. Any other
 * shape is malformed and is treated the same way. An element with no marker
 * of its own (a marker array shorter than the list) is not known to be public.
 * An element, or a nested object, marked whole (`true`) is withheld too, at
 * every level, the last included: a row is never handed over with a `true`
 * marker, which a reader indexing into it would see as "nothing marked". In
 * each of those cases the rows are withheld and the caller is told.
 *
 * Every row returned carries a marker that is an object, or undefined.
 */
function rowsAt(values, sensitive, segments) {
  // `at` is the row's place: the index of every list item on the way to it.
  let level = [{ value: values, marker: rowMarker(sensitive), at: [] }];
  let withheld = false;
  for (const segment of segments) {
    const next = [];
    for (const { value, marker, at } of level) {
      if (marker === WITHHELD) { withheld = true; continue; }
      if (!value || typeof value !== "object" || Array.isArray(value)) continue;
      const inner = value[segment];
      const innerMarker = marker?.[segment];
      if (!Array.isArray(inner)) {
        if (inner !== undefined && inner !== null) next.push({ value: inner, marker: rowMarker(innerMarker), at });
        continue;
      }
      if (innerMarker !== undefined && innerMarker !== false && !Array.isArray(innerMarker)) { withheld = true; continue; }
      inner.forEach((item, index) => {
        if (Array.isArray(innerMarker) && index >= innerMarker.length) { withheld = true; return; }
        next.push({ value: item, marker: Array.isArray(innerMarker) ? rowMarker(innerMarker[index]) : undefined, at: [...at, index] });
      });
    }
    level = next;
  }
  const rows = [];
  for (const { value, marker, at } of level) {
    if (marker === WITHHELD) { withheld = true; continue; }
    rows.push({ row: value, marker, at: at.join(".") });
  }
  return { rows, withheld };
}

/** A marker rowsAt cannot index into: the value is marked whole, or the marker is malformed. */
const WITHHELD = Symbol("withheld");

/** A row's marker as rowsAt carries it: an object, undefined (nothing marked), or WITHHELD. */
function rowMarker(marker) {
  if (marker === undefined || marker === false) return undefined;
  if (marker !== null && typeof marker === "object" && !Array.isArray(marker)) return marker;
  return WITHHELD;
}

/**
 * The key, on a list row, naming the fields the document marks sensitive.
 * Withheld is not absent: a field that is not there may take a default (a
 * port's protocol, Knative's 8080), and one that is withheld never does. It
 * cannot be a field's own name: a mapping path holds no parenthesis.
 */
export const WITHHELD_FIELDS = "(withheld)";

/** The ONE generic importer: a resource of a mapped type in, a fact out. */
export function importResource(resource, entry, references, expressions) {
  const { values, sensitive } = resource;
  const attrs = {};
  for (const path of entry.read ?? []) {
    const value = pickPath(values, sensitive, path);
    if (value !== undefined) attrs[path] = value;
  }
  // A top-level list of strings, read whole or not at all: any marker on it
  // other than "nothing here is sensitive" withholds it.
  for (const path of entry.strings ?? []) {
    const list = getPath(values, path);
    if (!Array.isArray(list)) continue;
    if (isMarkedSensitive(markerAt(sensitive, path))) { attrs[`${path}Withheld`] = true; continue; }
    attrs[path] = list.filter((item) => typeof item === "string");
  }
  // Whether a block is there. A marker that withholds it does not say it is
  // not, so it counts as there: fail closed.
  for (const path of entry.present ?? []) {
    const block = getPath(values, path);
    const there = Array.isArray(block) ? block.length > 0 : block !== undefined && block !== null;
    (attrs.present ??= {})[path] = there || isMarkedSensitive(markerAt(sensitive, path));
  }
  attrs.ids = {};
  for (const path of entry.ids ?? []) {
    const value = pickPath(values, sensitive, path);
    if (value !== undefined) attrs.ids[path] = value;
  }
  for (const list of entry.lists ?? []) {
    const key = list.path.split(".").pop();
    const { rows, withheld } = rowsAt(values, sensitive, list.path.split("."));
    attrs[key] = [];
    if (withheld) attrs[`${key}Withheld`] = true;
    for (const { row, marker, at } of rows) {
      if (!row || typeof row !== "object") continue;
      // A field may be a path through nested objects (`valueFrom.secretKeyRef.name`).
      const picked = {};
      const withheldFields = [];
      for (const path of list.read ?? []) {
        const value = pickPath(row, marker, path);
        if (value !== undefined) picked[path] = value;
        else if (isMarkedSensitive(markerAt(marker, path))) withheldFields.push(path);
      }
      for (const name of list.strings ?? []) {
        // A list of strings is read whole or not at all: any marker on it
        // other than "nothing here is sensitive" withholds it.
        if (!Array.isArray(row[name])) continue;
        if (isMarkedSensitive(markerAt(marker, name))) { withheldFields.push(name); continue; }
        const strings = row[name].filter((item) => typeof item === "string");
        if (strings.length > 0) picked[name] = strings;
      }
      // A row whose every field is withheld is still a row: a port that is
      // there, unread, is not a port that is not there.
      if (withheldFields.length > 0) picked[WITHHELD_FIELDS] = withheldFields;
      if (Object.keys(picked).length > 0) attrs[key].push(atRow(picked, at));
    }
  }
  // A map of strings read whole (a selector, a pod template's labels). Label
  // keys and values are not secrets, but the document's own marker is still
  // obeyed: any sensitivity on the map withholds all of it.
  for (const path of entry.maps ?? []) {
    const map = getPath(values, path);
    if (!map || typeof map !== "object" || Array.isArray(map)) continue;
    if (isMarkedSensitive(markerAt(sensitive, path))) continue;
    const pairs = Object.entries(map).filter(([, v]) => typeof v === "string");
    if (pairs.length) (attrs.maps ??= {})[path] = Object.fromEntries(pairs);
  }
  // Configuration references (plan documents), for the attributes the mapping names only.
  const kept = {};
  for (const attr of entry.referenceAttrs ?? []) {
    const addresses = references && Object.hasOwn(references, attr) ? references[attr] : undefined;
    if (Array.isArray(addresses) && addresses.length) kept[attr] = addresses;
  }
  if (Object.keys(kept).length) attrs.references = kept;
  // Where inside a nested block each kept reference is written ("env X").
  const sites = {};
  for (const attr of Object.keys(kept)) {
    const found = references?.[SITES]?.[attr];
    if (Array.isArray(found) && found.length) sites[attr] = found.map(({ address, where }) => ({ address, where }));
  }
  if (Object.keys(sites).length) attrs.referenceSites = sites;
  // What the configuration says about each row of a list the mapping names
  // (plan documents). Read from the source as written, so it is there even
  // when the planned list is withheld as sensitive.
  if (expressions) {
    const configured = {};
    for (const list of entry.configLists ?? []) {
      const rows = configuredRows(expressions, list.path, list.fields);
      if (rows.length) configured[list.path.split(".").pop()] = rows;
    }
    if (Object.keys(configured).length) attrs.configured = configured;
  }
  // An object held whole is one expression in the configuration, so where
  // each of its values comes from is not written down. What the expression
  // takes from at all is: the report needs it to know whether a value in the
  // object is the source's own text (ADR-0073, amendment of 2026-11-23).
  if (resource.heldIn !== undefined && expressions) {
    const sources = expressionSources(expressions[resource.heldIn]);
    if (sources) attrs.takenFrom = sources;
  }
  // An entry that says where the name is gets that name, or none. Falling
  // back to the Terraform label would name the resource after something the
  // document never said it is called, and its address would be built from it.
  const named = entry.name === undefined ? resource.name : pickPath(values, sensitive, entry.name);
  // Every entry is one of a mapping loaded and validated above, which names
  // its provider. Any other entry has no provider to state, and none is assumed.
  const source = SOURCE_OF.get(entry);
  if (source === undefined) throw new Error(`facts: ${resource.address} was read with an entry no loaded mapping holds, so the provider its fact comes from is unknown`);
  return makeFact({
    source,
    address: resource.address,
    type: resource.type,
    name: typeof named === "string" ? named : "",
    attrs,
  }, { entry });
}

/** Resource type → mapping entry. A type not listed here produces no fact. */
export const CLOUDFLARE_TYPES = CLOUDFLARE_MAPPING.types;

/** The value a fact exposes for a mapped join attribute, or undefined. */
function joinValue(fact, attr) {
  const entry = entryOf(fact);
  if (fact.attrs.ids?.[attr] !== undefined) return fact.attrs.ids[attr];
  if (fact.attrs[attr] !== undefined) return fact.attrs[attr];
  if (entry?.name === attr || (NAME_IS_SCRIPT_NAME.has(fact.type) && attr === "script_name")) return fact.name || undefined;
  return undefined;
}

function resolveOne(value, relation, facts) {
  if (typeof value !== "string" && typeof value !== "number") return null;
  return joinIndex(facts, relation).get(value) ?? null;
}

/**
 * value → first fact, for one relation over one facts array. Built once per
 * (facts, relation) and reused, so resolving N bindings is not N scans.
 */
const JOIN_INDEXES = new WeakMap();
function joinIndex(facts, relation) {
  let perFacts = JOIN_INDEXES.get(facts);
  if (!perFacts) JOIN_INDEXES.set(facts, (perFacts = new Map()));
  const key = `${relation.toType}\u0000${relation.toAttr}`;
  let index = perFacts.get(key);
  if (!index) {
    index = new Map();
    const types = relation.toType === WORKER_TYPE ? WORKER_FACT_TYPES : new Set([relation.toType]);
    for (const fact of facts) {
      if (!types.has(fact.type)) continue;
      const value = joinValue(fact, relation.toAttr);
      if (value !== undefined && !index.has(value)) index.set(value, fact);
    }
    perFacts.set(key, index);
  }
  return index;
}

/** A relation's target attributes, in the order they are tried. */
const targetAttrs = (relation) => (Array.isArray(relation.toAttr) ? relation.toAttr : [relation.toAttr]);
const isScoped = (relation) => Array.isArray(relation.toAttr) || relation.scope !== undefined || relation.stripPrefix !== undefined;

/**
 * Resolve a relation that declares alternatives, a scope, or a prefix.
 *
 * Providers let one attribute name its target in more than one spelling, and
 * state often holds the target's full identifier where the target's own `name`
 * is short. Every provider also exposes that full identifier as an attribute
 * of the target (`id`, `arn`). So the mapping lists the target attributes to
 * compare against, most exact first, and each comparison is plain equality.
 * No identifier is parsed.
 *
 * - `toAttr` may be a list: each is tried in order.
 * - `scope` lists attributes (a project, a region, an account) that must be
 *   equal wherever BOTH resources state them. A candidate is dropped only by a
 *   stated difference.
 * - `stripPrefix` removes one declared leading string from the value first.
 *
 * The first attribute with exactly one candidate wins. Several candidates on
 * the same attribute give null: one is never picked.
 */
function resolveScoped(value, fact, relation, facts) {
  if (typeof value !== "string" && typeof value !== "number") return null;
  let wanted = value;
  if (typeof wanted === "string" && relation.stripPrefix !== undefined && wanted.startsWith(relation.stripPrefix)) {
    wanted = wanted.slice(relation.stripPrefix.length);
  }
  const scope = (relation.scope ?? []).map((attr) => [attr, joinValue(fact, attr)]).filter(([, stated]) => stated !== undefined);
  const inScope = (target) => scope.every(([attr, stated]) => {
    const theirs = joinValue(target, attr);
    return theirs === undefined || theirs === stated;
  });
  for (const toAttr of targetAttrs(relation)) {
    const candidates = facts.filter((target) => target.type === relation.toType && joinValue(target, toAttr) === wanted && inScope(target));
    if (candidates.length === 1) return candidates[0];
    if (candidates.length > 1) return null;
  }
  return null;
}

const ADDRESS_INDEXES = new WeakMap();
function factAt(facts, address) {
  let index = ADDRESS_INDEXES.get(facts);
  if (!index) ADDRESS_INDEXES.set(facts, (index = new Map(facts.map((f) => [f.address, f]))));
  return index.get(address) ?? null;
}

/**
 * The fact a PLAN's configuration says `fact.<attr>` references, when exactly
 * one referenced address has the relation's target type. Zero or several
 * candidates give null: one is never picked.
 */
function resolveByReference(fact, relation, facts) {
  const candidates = (fact.attrs.references?.[relation.attr] ?? []).filter((a) => a.split(".")[0] === relation.toType);
  if (candidates.length !== 1) return null;
  const target = factAt(facts, candidates[0]);
  return target && target.type === relation.toType ? target : null;
}

/**
 * Resolve a resource's mapped relations. Returns `[{attr, value, to: fact | null}]`;
 * `null` means "not in this document". Order: exact value equality (see
 * resolveScoped for a relation with alternatives or a scope); then, only
 * when `kind` is "plan" and the value resolved nothing, the configuration's
 * references (see resolveByReference). A state document never uses references.
 */
export function resolveRelations(fact, facts, kind) {
  const entry = entryOf(fact);
  return (entry?.relations ?? []).map((relation) => {
    const value = joinValue(fact, relation.attr);
    let to = isScoped(relation) ? resolveScoped(value, fact, relation, facts) : resolveOne(value, relation, facts);
    if (!to && kind === "plan") to = resolveByReference(fact, relation, facts);
    return { attr: relation.attr, value, to };
  });
}

/** Resolve a Worker binding through the mapping's binding relations. */
export function resolveBinding(binding, facts) {
  for (const relation of relationsFor(binding)) {
    const to = resolveOne(binding[relation.attr], relation, facts);
    if (to) return { value: binding[relation.attr], to };
  }
  const first = relationsFor(binding)[0];
  return { value: first ? binding[first.attr] : undefined, to: null };
}

/** True when a binding names another workload (as opposed to storage or config). */
export function isWorkloadBinding(binding) {
  return relationsFor(binding).some((r) => r.toType === WORKER_TYPE);
}

/** The workload a workload-binding names, or "" when the document does not say. */
export function bindingTarget(binding) {
  const relation = relationsFor(binding).find((r) => r.toType === WORKER_TYPE);
  return relation ? (binding[relation.attr] ?? "") : "";
}
